function sorted(a, b) {
    const nameA = typeof a == "string" ? a : a.items[0] || a.label;
    const nameB = typeof b == "string" ? b : b.items[0] || b.label;
    return nameA > nameB ? 1 : -1;
}

// One addon category: label, collapsed state and listing page come from the folder's
// _category_.json; the addons inside are autogenerated from the folder.
const fs = require("fs");
const path = require("path");
function addonCategory(dir) {
    const meta = JSON.parse(
        fs.readFileSync(path.join(__dirname, "docs", "addons", dir, "_category_.json"), "utf8")
    );
    return {
        type: "category",
        label: meta.label,
        collapsed: meta.collapsed !== false,
        link: meta.link,
        items: [{ type: "autogenerated", dirName: `addons/${dir}` }],
    };
}

